Two independent defects combine to make hash-only `/open` never accrue claimable credits.

**Defect 1 — `open.go:120-123` gates `RecordCredit` on body fields the spec doesn't send.** The documented spec `OpenPageRequest` carries only `hash`; `PublisherID`/`Domain` are never present, so the gate `if req.PublisherID != "" && req.Domain != ""` is always false and no credit row is ever created. Fix: drop the body gating and resolve `hash → URL → domain → publisher` from `content_hash_store` + `verified_domains`, then credit the resolved publisher.

```go
// open.go — spec-compliant request carries ONLY hash
type OpenPageRequest struct {
    Hash string `json:"hash" binding:"required"`
}

type OpenPageResponse struct {
    OK       bool   `json:"ok"`
    URL      string `json:"url,omitempty"`
    Credited bool   `json:"credited"`
}

func (s *Server) Open(c *gin.Context) {
    var req OpenPageRequest
    if err := c.ShouldBindJSON(&req); err != nil {
        c.JSON(http.StatusBadRequest, gin.H{"error": "hash required"})
        return
    }

    // 1. hash -> url (content_hash_store), case-insensitive
    url, err := s.contentHashes.URLByHash(strings.ToLower(req.Hash))
    if err != nil || url == "" {
        c.JSON(http.StatusNotFound, gin.H{"error": "unknown content hash"})
        return
    }

    // 2. url -> domain
    u, err := urlpkg.Parse(url)
    if err != nil || u.Host == "" {
        c.JSON(http.StatusUnprocessableEntity, gin.H{"error": "unresolvable url"})
        return
    }

    // 3. domain -> publisher (verified_domains)
    publisher, ok, err := s.verifiedDomains.PublisherByDomain(u.Host)
    if err != nil {
        c.JSON(http.StatusInternalServerError, gin.H{"error": "domain lookup failed"})
        return
    }
    if !ok {
        // open still recorded; domain not verified -> nothing claimable
        c.JSON(http.StatusOK, OpenPageResponse{OK: true, URL: url, Credited: false})
        return
    }

    // 4. credit the RESOLVED publisher (previously gated on body fields)
    if err := s.credits.RecordCredit(c.Request.Context(), publisher, u.Host, creditPerOpen); err != nil {
        c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to record credit"})
        return
    }
    c.JSON(http.StatusOK, OpenPageResponse{OK: true, URL: url, Credited: true})
}
```

