// RecordCredit: idempotent upsert that accumulates the shadow balance
func (r *CreditRepo) RecordCredit(ctx context.Context, publisherID, domain string, amount int64) error {
    const q = `
        INSERT INTO publisher_credits (publisher_id, domain, shadow_credits, updated_at)
        VALUES ($1, $2, $3, now())
        ON CONFLICT (publisher_id, domain)
        DO UPDATE SET shadow_credits = publisher_credits.shadow_credits + EXCLUDED.shadow_credits,
                      updated_at = now()`
    _, err := r.db.ExecContext(ctx, q, publisherID, domain, amount)
    return err
}
```

**Defect 2 — `ClaimDomainCredits` `UPDATE ... RETURNING shadow_credits` returns the post-update value.** Setting `shadow_credits = 0` and returning the column yields `0`, so every claim pays out zero even when shadow credits accrued. Fix: a data-modifying CTE — a `snapshot` CTE with `FOR UPDATE` reads the **pre-update** value (and takes the row lock), the `zeroed` CTE zeroes it, and the outer query returns the snapshot amount. The whole statement is atomic; the row lock serializes concurrent claims.

```go
func (r *CreditRepo) ClaimDomainCredits(ctx context.Context, publisherID, domain string) (int64, error) {
    const q = `
        WITH snapshot AS (
            SELECT publisher_id, shadow_credits AS amount
            FROM publisher_credits
            WHERE publisher_id = $1 AND domain = $2
            FOR UPDATE
        ),
        zeroed AS (
            UPDATE publisher_credits
            SET shadow_credits = 0,
                updated_at = now()
            WHERE publisher_id = $1 AND domain = $2
            RETURNING publisher_id
        )
        SELECT s.amount
        FROM snapshot s
        JOIN zeroed z ON z.publisher_id = s.publisher_id`
    var claimed int64
    err := r.db.QueryRowContext(ctx, q, publisherID, domain).Scan(&claimed)
    if errors.Is(err, sql.ErrNoRows) {
        return 0, nil // nothing accrued
    }
    return claimed, err
}
```
